"""Generate the human-readable catalogs in system/generated/.

These files are derived from the registries and must never be edited by
hand; CI runs `generate-registry-docs.py --check` to catch drift.
"""

from __future__ import annotations

from .registry import Registries, transitive_dependencies

HEADER = ("> Generated by `scripts/generate-registry-docs.py` from "
          "`system/registry/`.\n> Do not edit by hand.\n")
FAMILIES = [("core", "Core Agents"), ("quran", "Quran Program Agents"),
            ("daily", "Daily Practice Agents"),
            ("learning", "Learning System Agents")]


def _cell(value) -> str:
    if isinstance(value, list):
        value = "; ".join(str(v) for v in value) if value else "none"
    return str(value).replace("|", "\\|").replace("\n", " ")


def _anchor(text: str) -> str:
    return text.lower().replace(" ", "-")


def agent_catalog(reg: Registries) -> str:
    tiers = {t["tier"]: t["name"] for t in reg.permissions["tiers"]}
    out = ["# Agent Catalog", "", HEADER,
           f"{len(reg.agents)} agents. Architecture: "
           "[Agent Registry](../../docs/architecture/02-agent-registry.md).",
           ""]
    for family, title in FAMILIES:
        members = sorted((a for a in reg.agents.values()
                          if a["family"] == family),
                         key=lambda a: a["agent_id"])
        out += [f"## {title}", "",
                "| Agent | Tier | Class | Model | Gate |",
                "| --- | :-: | :-: | --- | :-: |"]
        for agent in members:
            out.append(
                f"| [{agent['name']}](#{_anchor(agent['agent_id'])}) | "
                f"{agent['permission_level']} | {agent['complexity_class']}"
                f" | {agent['default_model']} | "
                f"{agent['quality']['review_gate']} |")
        out.append("")
        for agent in members:
            budget = agent["token_budget"]
            rows = [
                ("Name", agent["name"]),
                ("Purpose", " ".join(agent["purpose"].split())),
                ("Responsibilities", agent["responsibilities"]),
                ("Inputs", agent["inputs"]),
                ("Outputs", agent["outputs"]),
                ("Complexity class", agent["complexity_class"]),
                ("Default model", f"{agent['default_model']} "
                 f"(`{reg.model(agent['default_model'])['model_id']}`)"),
                ("Fallback model", f"{agent['fallback_model']} "
                 f"(`{reg.model(agent['fallback_model'])['model_id']}`)"),
                ("Permission tier", f"{agent['permission_level']} "
                 f"({tiers[agent['permission_level']]})"),
                ("Required skills", agent["required_skills"]),
                ("Memory read", agent["memory"]["read"]),
                ("Memory write", agent["memory"]["write"] or ["none"]),
                ("Token budget", f"{budget['input']:,} in / "
                 f"{budget['output']:,} out"),
                ("Explanation levels",
                 agent.get("explanation_levels") or ["n/a"]),
                ("Escalation rules", agent["escalation_rules"] or ["none"]),
                ("Evaluation metrics",
                 [f"{m['metric']} {m['target']}"
                  for m in agent["evaluation_metrics"]]),
                ("Validation", agent["quality"]["validation"]),
                ("Failure handling", agent["quality"]["failure_handling"]),
                ("Review gate", agent["quality"]["review_gate"]),
                ("Human approval", agent["quality"]["human_approval"]),
                ("Reports to", agent["reports_to"]),
                ("Collaborates with", agent["collaborates_with"]),
            ]
            out += [f"### {agent['agent_id']}", "", "| Field | Value |",
                    "| --- | --- |"]
            out += [f"| {k} | {_cell(v)} |" for k, v in rows]
            out.append("")
    return "\n".join(out).rstrip() + "\n"


def skill_catalog(reg: Registries) -> str:
    users: dict[str, list[str]] = {s: [] for s in reg.skills}
    for agent in reg.agents.values():
        for skill in agent["required_skills"]:
            users.setdefault(skill, []).append(agent["agent_id"])
    out = ["# Skill Catalog", "", HEADER,
           f"{len(reg.skills)} skills. Architecture: "
           "[Skill Registry](../../docs/architecture/03-skill-registry.md).",
           "", "## Summary", "",
           "| Skill | Class | Execution | Model | Fallback | Budget |",
           "| --- | :-: | --- | --- | --- | ---: |"]
    ordered = sorted(reg.skills.values(),
                     key=lambda s: (s["complexity_class"], s["skill_id"]))
    for skill in ordered:
        budget = skill["token_budget"]
        out.append(f"| [{skill['name']}](#{skill['skill_id']}) | "
                   f"{skill['complexity_class']} | {skill['execution']} | "
                   f"{skill['recommended_model']} | "
                   f"{skill['fallback_model']} | "
                   f"{budget['input']:,} / {budget['output']:,} |")
    out += ["", "## Skills", ""]
    for skill in ordered:
        rows = [
            ("Name", skill["name"]),
            ("Purpose", skill["purpose"]),
            ("Input", skill["input"]),
            ("Output", skill["output"]),
            ("Dependencies", skill["dependencies"] or ["none"]),
            ("All dependencies (transitive)",
             transitive_dependencies(reg.skills, skill["skill_id"])
             or ["none"]),
            ("Complexity class", skill["complexity_class"]),
            ("Execution", skill["execution"]),
            ("Recommended model", skill["recommended_model"]),
            ("Fallback model", skill["fallback_model"]),
            ("Token budget", f"{skill['token_budget']['input']:,} in / "
             f"{skill['token_budget']['output']:,} out"),
            ("Used by agents", sorted(users.get(skill["skill_id"], []))
             or ["none"]),
        ]
        out += [f"### {skill['skill_id']}", "", "| Field | Value |",
                "| --- | --- |"]
        out += [f"| {k} | {_cell(v)} |" for k, v in rows]
        out.append("")
    return "\n".join(out).rstrip() + "\n"


def routing_matrix(reg: Registries) -> str:
    forbidden = set(reg.routing["downgrade_rules"]["forbidden_on_opus"])
    batch = set(reg.routing["downgrade_rules"].get("batch_eligible", []))
    out = ["# Routing Matrix", "", HEADER,
           "Architecture: [Model Routing Framework]"
           "(../../docs/architecture/05-model-routing-framework.md).", "",
           "## Complexity Classes", "",
           "| Class | Name | Model | Model ID | Effort | Input cap | "
           "Output cap |",
           "| :-: | --- | --- | --- | --- | ---: | ---: |"]
    for cls in reg.routing["complexity_classes"]:
        model = reg.model(cls["model"])
        out.append(f"| {cls['class']} | {cls['name']} | {cls['model']} | "
                   f"`{model['model_id']}` | {cls['effort']} | "
                   f"{model['budget']['max_input_tokens']:,} | "
                   f"{model['budget']['max_output_tokens']:,} |")
    out += ["", "## Task Types", "",
            "| Task | Class | Execution | Model | Never on Opus | Batch |",
            "| --- | :-: | --- | --- | :-: | :-: |"]
    for task in sorted(reg.routing["task_types"],
                       key=lambda t: (t["class"], t["task"])):
        model = "none" if task["execution"] == "script" else \
            reg.complexity_class(task["class"])["model"]
        out.append(f"| `{task['task']}` | {task['class']} | "
                   f"{task['execution']} | {model} | "
                   f"{'yes' if task['task'] in forbidden else ''} | "
                   f"{'yes' if task['task'] in batch else ''} |")
    out += ["", "## Escalation Triggers", "",
            "| From | To | Signal | Condition | Reason |",
            "| --- | --- | --- | --- | --- |"]
    for rule in reg.routing["escalation_rules"]:
        for trig in rule["triggers"]:
            out.append(f"| {rule['from']} | {rule['to']} | "
                       f"`{trig['signal']}` | {trig['operator']} "
                       f"{trig['value']} | {trig['reason']} |")
    return "\n".join(out).rstrip() + "\n"


def build(reg: Registries) -> dict[str, str]:
    return {
        "system/generated/agent-catalog.md": agent_catalog(reg),
        "system/generated/skill-catalog.md": skill_catalog(reg),
        "system/generated/routing-matrix.md": routing_matrix(reg),
    }
